func WorkflowDefinitionByID(id string) (WorkflowDefinition, bool) {
	for _, definition := range DefaultWorkflowDefinitions {
		if definition.ID == id {
			return definition, true
		}
	}
	return WorkflowDefinition{}, false
}
func WorkflowDefinitionsForPhase(phase string) []WorkflowDefinition {
	definitions := make([]WorkflowDefinition, 0)
	for _, definition := range DefaultWorkflowDefinitions {
		if definition.Phase == phase {
			definitions = append(definitions, definition)
		}
	}
	return definitions
}
